package com.gomgomapps.math.core;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;import java.io.*;
public class ShapeStructureRelationsTest {
 @Test public void distinctVisibleOutlinesRemainConvexAndDoNotInflateFacts()throws Exception{Generator g=new Generator(new Random(100307));for(String id:List.of("el_shape_sides","el_shape_classify")){Set<String> drawings=new HashSet<>();for(int sample=0;sample<1600;sample++){Question q=g.next(id,List.of(),false);String signature=q.signature();StringBuilder key=new StringBuilder();for(int k=0;k<q.diagram.values.length;k++){double[][] points=ShapeStructureRelations.outline(q.diagram,k);if(points.length==0){key.append("circle;");continue;}assertEquals((int)q.diagram.values[k],points.length);List<String> vertices=new ArrayList<>();for(int i=0;i<points.length;i++){double[] a=points[i],b=points[(i+1)%points.length],c=points[(i+2)%points.length];double cross=(b[0]-a[0])*(c[1]-b[1])-(b[1]-a[1])*(c[0]-b[0]);assertTrue("Strictly convex visible outline",cross>0);vertices.add(Math.round(a[0]*1e6)+","+Math.round(a[1]*1e6));}Collections.sort(vertices);key.append(vertices).append(';');}drawings.add(key.toString());q.diagram.scaledHorizontally(id.equals("el_shape_sides")?new double[]{.7}:new double[]{.7,.8,.9,1});assertEquals("Drawing stretch must not create another fact",signature,q.signature());}assertTrue(id+" distinct visible geometry "+drawings.size(),drawings.size()>=100);}StudyDiagram plain=new StudyDiagram("polygon",new double[]{4});assertNull(plain.rotationDegrees);assertNull(plain.horizontalScale);double[] scale={.7};StudyDiagram d=plain.rotated(15).scaledHorizontally(scale);scale[0]=.9;assertEquals(.7,d.horizontalScale[0],0);ByteArrayOutputStream b=new ByteArrayOutputStream();new ObjectOutputStream(b).writeObject(d);StudyDiagram loaded=(StudyDiagram)new ObjectInputStream(new ByteArrayInputStream(b.toByteArray())).readObject();assertArrayEquals(d.horizontalScale,loaded.horizontalScale,0);assertArrayEquals(d.rotationDegrees,loaded.rotationDegrees,0);}
 private static List<Integer> expected(Question q){if(q.skillId.equals("el_shape_sides"))return List.of((int)q.diagram.values[0]);if(q.skillId.equals("el_shape_classify")){List<Integer> values=new ArrayList<>();int triangles=0;for(double v:q.diagram.values){values.add((int)v);if(v==3)triangles++;}values.add(triangles);return values;}if(q.prompt.contains("면, 모서리"))return List.of(6,12,8);return List.of(q.prompt.contains("모서리는")?12:q.prompt.contains("꼭짓점은")?8:6);}
 @Test public void visibleShapeCountsAreIndependentAndNeverTransferred(){Generator g=new Generator(new Random(100301));for(String id:ShapeStructureRelations.IDS){Set<String> drawings=new HashSet<>(),facts=new HashSet<>();for(int i=0;i<1600;i++){Question q=g.next(id,List.of(),i%2==0);List<Integer> counts=expected(q);if(id.equals("el_shape_classify"))assertEquals(""+counts.get(4),q.answers[0]);else for(int k=0;k<q.answers.length;k++)assertEquals(""+counts.get(k),q.answers[k]);facts.add(q.prompt+Arrays.toString(q.answers));drawings.add(q.prompt+Arrays.toString(q.diagram.values)+Arrays.toString(q.diagram.rotationDegrees));String signature=q.signature();String[] answers=q.answers.clone();HelpPlan p=HelpPlan.forQuestion(q);var frames=ShapeStructureRelations.frames(q);assertEquals(counts.size(),frames.size());assertFalse(p.canTransfer());HelpPlan.Draft d=p.restore(null,q.id);for(int k=0;k<p.size();k++){assertEquals(""+counts.get(k),frames.get(k).expected());assertTrue(p.step(k).accepts(""+counts.get(k)));assertFalse(p.step(k).accepts(""));assertFalse(p.step(k).accepts(""+(counts.get(k)+1)));assertFalse(frames.get(k).label().matches(".*[0-9].*"));d.entries.set(k,""+counts.get(k));d.stage++;d.entries.add("");}assertEquals(signature,q.signature());assertArrayEquals(answers,q.answers);q.answers=new String[]{"999"};q.expression="999+1";q.studyGuide=new StudyGuide().step("old","999 = ","","999");p=HelpPlan.forQuestion(q);assertFalse(p.canTransfer());assertEquals(""+counts.get(counts.size()-1),p.enteredAnswer(d));}assertTrue(id+" drawings "+drawings.size(),drawings.size()>=100);if(id.equals("el_shape_sides"))assertEquals(6,facts.size());if(id.equals("el_3d_elements"))assertEquals(4,facts.size());}}
 @Test public void allCuboidPromptsAndMalformedShapesAreHandled(){Generator g=new Generator(new Random(100302));Set<Integer> arities=new HashSet<>();Set<String> parts=new HashSet<>();for(int i=0;i<300;i++){Question q=g.next("el_3d_elements",List.of(),false);arities.add(q.answers.length);parts.add(q.prompt);for(double v:q.diagram.values)assertTrue(v>=2&&v<=9&&v==Math.rint(v));HelpPlan p=HelpPlan.forQuestion(q);for(int stage=0;stage<p.size();stage++){StudyDiagram d=ShapeStructureRelations.teachingDiagram(q,stage);assertEquals(ShapeStructureRelations.frames(q).get(stage).diagramType(),d.type);assertArrayEquals(q.diagram.values,d.values,0);}}assertEquals(Set.of(1,3),arities);assertEquals(4,parts.size());Question q=g.next("el_shape_sides",List.of(),false);q.diagram.values[0]=9;assertTrue(ShapeStructureRelations.frames(q).isEmpty());q=g.next("el_shape_classify",List.of(),false);q.diagram.values[0]=2;assertTrue(ShapeStructureRelations.frames(q).isEmpty());q=g.next("el_3d_elements",List.of(),false);q.diagram.values[0]=Double.NaN;assertTrue(ShapeStructureRelations.frames(q).isEmpty());}
 @Test public void presentationRotationDoesNotCreateNewFactsAndDraftsRestore()throws Exception{for(String id:ShapeStructureRelations.IDS){Question q=new Generator(new Random(100303)).next(id,List.of(),false);String sig=q.signature();if(!id.equals("el_3d_elements")){q.diagram.rotated(id.equals("el_shape_sides")?new double[]{30}:new double[]{30,60,90,120});assertEquals(sig,q.signature());}HelpPlan p=HelpPlan.forQuestion(q);HelpPlan.Draft old=new HelpPlan.Draft();old.questionId=q.id;old.stage=1;old.entries.add("999");assertEquals(0,p.restore(old,q.id).stage);HelpPlan.Draft d=p.restore(null,q.id);d.entries.set(0,ShapeStructureRelations.frames(q).get(0).expected());d.stage=1;d.entries.add("");ByteArrayOutputStream b=new ByteArrayOutputStream();new ObjectOutputStream(b).writeObject(d);HelpPlan.Draft loaded=(HelpPlan.Draft)new ObjectInputStream(new ByteArrayInputStream(b.toByteArray())).readObject();assertEquals(1,p.restore(loaded,q.id).stage);assertEquals(d.entries.get(0),p.restore(loaded,q.id).entries.get(0));}}
}
